import requests
from typing import Dict, Any


def get_weather_from_provider(api_url: str) -> dict:
    """
    Fetches weather data from a specified API provider.

    Args:
        api_url: The URL of the weather data provider's API endpoint

    Returns:
        A dictionary containing the weather data from the API response

    Raises:
        requests.exceptions.RequestException: If the request fails or times out
        ValueError: If the response contains invalid JSON
    """
    try:
        response = requests.get(api_url, timeout=10)
        response.raise_for_status()  # Raises an HTTPError for bad status codes
        return response.json()
    except requests.exceptions.Timeout:
        raise requests.exceptions.RequestException(
            f"Request to {api_url} timed out"
        )
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.RequestException(
            f"HTTP error occurred: {e.response.status_code} - {e.response.reason}"
        )
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(
            f"Request failed: {str(e)}"
        )
    except ValueError as e:
        raise ValueError(f"Invalid JSON response from {api_url}: {str(e)}")
